"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { CopyButton } from "./ticket-detail";
import { SyntheticNotice } from "./labels";

// End-of-shift handoff: the Markdown the endpoint generates, ready to paste
// into the team channel. Generated by code from stored state; regenerate any
// time — reading it changes nothing.

export function HandoffView() {
  const [md, setMd] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);

  async function load() {
    setFailed(false);
    try {
      const res = await fetch("/api/support/handoff?format=md");
      if (!res.ok) return setFailed(true);
      setMd(await res.text());
    } catch {
      setFailed(true);
    }
  }

  useEffect(() => {
    void load();
  }, []);

  return (
    <div className="flex flex-col gap-4">
      <Link href="/support" className="text-sm text-[var(--link)] underline underline-offset-2">← 工单队列 Ticket queue</Link>
      <header className="flex flex-col gap-2">
        <p className="caption">Shift handoff</p>
        <h1 className="text-3xl font-semibold text-[var(--brand)]">交接班摘要</h1>
        <p className="max-w-2xl text-sm text-slate-600">
          所有未关闭工单，按 SLA 风险分组：最后动作、下一步、阻塞项。由代码从已存状态生成，不经大模型。
          <br />
          Every open ticket grouped by SLA risk, with last action, next step and blocker. Generated by code from stored
          state — no model.
        </p>
        <SyntheticNotice />
      </header>
      {failed && <p role="alert" className="text-sm text-red-800">生成失败，请重试。Could not generate the handoff.</p>}
      {md === null && !failed && <p className="text-sm text-slate-600">生成中… Generating…</p>}
      {md !== null && (
        <section className="rounded border border-slate-200 bg-white p-4">
          <div className="mb-2 flex items-center justify-end gap-2">
            <button type="button" onClick={() => void load()} className="rounded border border-slate-300 bg-white px-2 py-1 text-xs text-slate-700">
              重新生成 Regenerate
            </button>
            <CopyButton text={md} />
          </div>
          <pre data-testid="handoff-markdown" className="overflow-auto whitespace-pre-wrap font-mono text-xs leading-relaxed text-slate-800">{md}</pre>
        </section>
      )}
    </div>
  );
}
